int main(void) {
    int w, h, n;
    while (scanf("%d %d %d", &w, &h, &n) == 3) {
        if (w == 0 && h == 0 && n == 0) break;

        Block *b = (Block *)malloc(sizeof(Block) * n);
        int *board = (int *)calloc((w + 2) * (h + 2), sizeof(int));

        for (int i = 0; i < n; i++) {
            scanf("%d %d %d %d", &b[i].x, &b[i].y, &b[i].c, &b[i].d);

            int bw = (b[i].d == 0) ? 4 : 2;
            int bh = (b[i].d == 0) ? 2 : 4;

            for (int dy = 0; dy < bh; dy++) {
                for (int dx = 0; dx < bw; dx++) {
                    int xx = b[i].x + dx;
                    int yy = b[i].y + dy;
                    board[yy * (w + 2) + xx] = b[i].c;
                }
            }
        }

        int sx, sy, gx, gy;
        scanf("%d %d %d %d", &sx, &sy, &gx, &gy);

        int startColor = board[sy * (w + 2) + sx];
        int goalColor  = board[gy * (w + 2) + gx];

        if (startColor == 0 || goalColor == 0 || startColor != goalColor) {
            puts("NG");
            free(b);
            free(board);
            continue;
        }

        int size = (w + 2) * (h + 2);
        char *vis = (char *)calloc(size, sizeof(char));
        Node *q = (Node *)malloc(sizeof(Node) * size);
        int head = 0, tail = 0;

        q[tail++] = (Node){sx, sy};
        vis[sy * (w + 2) + sx] = 1;

        int found = 0;
        int dx[4] = {1, -1, 0, 0};
        int dy[4] = {0, 0, 1, -1};

        while (head < tail) {
            Node cur = q[head++];
            if (cur.x == gx && cur.y == gy) {
                found = 1;
                break;
            }

            for (int k = 0; k < 4; k++) {
                int nx = cur.x + dx[k];
                int ny = cur.y + dy[k];
                int idx = ny * (w + 2) + nx;
                if (!vis[idx] && board[idx] == startColor) {
                    vis[idx] = 1;
                    q[tail++] = (Node){nx, ny};
                }
            }
        }

        puts(found ? "OK" : "NG");

        free(b);
        free(board);
        free(vis);
        free(q);
    }
    return 0;
}

