        x--; y--; // convert to 0-based
        blocks[i] = {x, y, dir, color};

        // Fill board with block id
        if (dir == 0) { // horizontal (2 rows, 4 cols)
            for (int r = y; r < y + 2; r++) {
                for (int c = x; c < x + 4; c++) {
                    board[r][c] = i;
                }
            }
        } else { // vertical (4 rows, 2 cols)
            for (int r = y; r < y + 4; r++) {
                for (int c = x; c < x + 2; c++) {
                    board[r][c] = i;
                }
            }
        }
    }

    int sx, sy, gx, gy;
    cin >> sx >> sy >> gx >> gy;
    sx--; sy--; gx--; gy--;

    int start_id = board[sy][sx];
    int goal_id = board[gy][gx];

    if (start_id == -1 || goal_id == -1) {
        cout << "NG\n";
        return 0;
    }

    if (start_id == goal_id) {
        cout << "OK\n";
        return 0;
    }

    int start_color = blocks[start_id].color;
    int goal_color = blocks[goal_id].color;

    if (start_color != goal_color) {
        cout << "NG\n";
        return 0;
    }

    // BFS over blocks of the same color
    vector<bool> visited(n, false);
    queue<int> q;
    q.push(start_id);
    visited[start_id] = true;

    while (!q.empty()) {
        int cur = q.front(); q.pop();
        if (cur == goal_id) {
            cout << "OK\n";
            return 0;
        }

        int cx = blocks[cur].x;
        int cy = blocks[cur].y;
        int cdir = blocks[cur].dir;

        // Get all cell coordinates of current block
        vector<pair<int,int>> cells;
        if (cdir == 0) {
            for (int r = cy; r < cy + 2; r++)
                for (int c = cx; c < cx + 4; c++)
                    cells.emplace_back(r, c);
        } else {
            for (int r = cy; r < cy + 4; r++)
                for (int c = cx; c < cx + 2; c++)
                    cells.emplace_back(r, c);
        }

        // Check four directions for each boundary cell
        int dr[4] = {-1, 1, 0, 0};
        int dc[4] = {0, 0, -1, 1};

        for (auto [r, c] : cells) {
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= h || nc < 0 || nc >= w) continue;
                int nid = board[nr][nc];
                if (nid == -1) continue;
                if (visited[nid]) continue;
                if (blocks[nid].color != start_color) continue;
                visited[nid] = true;
                q.push(nid);
            }
        }
    }

    cout << "NG\n";
    return 0;
}

