                        board[r][c] = color;
                    }
                }
            } else { // vertical (width 2, height 4)
                for (int r = y; r < y + 4; r++) {
                    for (int c = x; c < x + 2; c++) {
                        board[r][c] = color;
                    }
                }
            }
        }

        // Read start and goal coordinates
        int sx = sc.nextInt() - 1;
        int sy = sc.nextInt() - 1;
        int gx = sc.nextInt() - 1;
