            boolean ok = false;
            if (1 <= sx && sx <= w && 1 <= sy && sy <= h &&
                1 <= gx && gx <= w && 1 <= gy && gy <= h) {
                int startColor = board[sy][sx];
                int goalColor = board[gy][gx];

                if (startColor != 0 && startColor == goalColor) {
                    boolean[][] vis = new boolean[h + 1][w + 1];
                    ArrayDeque<int[]> q = new ArrayDeque<>();
                    q.add(new int[]{sx, sy});
                    vis[sy][sx] = true;

                    int[] dx = {1, -1, 0, 0};
                    int[] dy = {0, 0, 1, -1};

                    while (!q.isEmpty()) {
                        int[] cur = q.poll();
                        int x = cur[0], y = cur[1];
                        if (x == gx && y == gy) {
                            ok = true;
                            break;
                        }
                        for (int k = 0; k < 4; k++) {
                            int nx = x + dx[k];
                            int ny = y + dy[k];
                            if (nx < 1 || nx > w || ny < 1 || ny > h) continue;
                            if (vis[ny][nx]) continue;
                            if (board[ny][nx] != startColor) continue;
                            vis[ny][nx] = true;
                            q.add(new int[]{nx, ny});
                        }
                    }
                }
            }

            out.append(ok ? "OK" : "NG").append('\n');
        }

        System.out.print(out.toString());
    }
}
